{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Erythromycin, a macrolide antibiotic with a macrocyclic lactone and sugar moieties, achieves only 0.1-2.5 µg/mL CSF versus 8-12 µg/mL serum in meningitis patients, demonstrating poor blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Tobramycin, a highly polar aminoglycoside containing multiple amino sugars, has very low or undetectable CSF concentrations in neonates, supporting poor CNS access for polar amino-sugar-containing macrolide-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Madecassoside, a large multi-glycoside natural product, was below the lower limit of quantification in rat brain after oral dosing, indicating that highly polar glycosylated macrocycles do not efficiently cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Clarithromycin, a more lipophilic macrolide, showed 25-45% CSF penetration in rabbits with pneumococcal meningitis, but this positive result was obtained under meningeal inflammation and with a less polar structure than the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Dictyostatin, a macrocyclic polyketide, showed good brain AUC in mice, but it lacks the polar amino sugar, multiple hydroxyls, and carboxylic acid that dominate the query's CNS-penetration liabilities.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, polar, amphoteric polyene macrolide with an amino sugar, multiple hydroxyls, and a carboxylic acid. Direct human CSF data for erythromycin, very low CSF for tobramycin, and absent brain exposure for madecassoside indicate that such polar macrocyclic glycosides/macrolides do not achieve meaningful CNS access. Positive clarithromycin and dictyostatin signals are explained by higher lipophilicity, inflamed meninges, or absence of the query's polar/ionizable groups, and do not outweigh the fail evidence.",
  "evidence_gaps": [
    "No direct amphotericin B brain/CSF pharmacokinetic record is present in the evidence set.",
    "All retrieved analogues have low Morgan similarity (<0.25), limiting quantitative transferability.",
    "Positive clarithromycin data were generated in meningitis with a disrupted blood-brain barrier.",
    "Some positive glycoside/saponin brain-detection studies are qualitative and may reflect low-level distribution or metabolites."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

